use std::str::FromStr;

pub fn parse_stof_like(input: &str) -> f32 {
    let trimmed = input.trim_start();
    let prefix_len = parse_prefix_len(trimmed).unwrap_or_else(|| panic!("stof"));
    f32::from_str(&trimmed[..prefix_len]).unwrap_or_else(|_| panic!("stof"))
}

fn parse_prefix_len(input: &str) -> Option<usize> {
    if input.is_empty() {
        return None;
    }

    let bytes = input.as_bytes();
    let mut index = 0;

    if matches!(bytes[index], b'+' | b'-') {
        index += 1;
        if index == bytes.len() {
            return None;
        }
    }

    let rest = input[index..].to_ascii_lowercase();

    if rest.starts_with("infinity") {
        return Some(index + "infinity".len());
    }

    if rest.starts_with("inf") {
        return Some(index + "inf".len());
    }

    if rest.starts_with("nan") {
        let mut end = index + "nan".len();
        if input.as_bytes().get(end) == Some(&b'(') {
            let mut scan = end + 1;
            while let Some(&byte) = input.as_bytes().get(scan) {
                scan += 1;
                if byte == b')' {
                    end = scan;
                    break;
                }
            }
        }
        return Some(end);
    }

    let mut scan = index;
    let mut digits_before = 0;

    while matches!(input.as_bytes().get(scan), Some(b'0'..=b'9')) {
        scan += 1;
        digits_before += 1;
    }

    let mut digits_after = 0;
    if input.as_bytes().get(scan) == Some(&b'.') {
        scan += 1;
        while matches!(input.as_bytes().get(scan), Some(b'0'..=b'9')) {
            scan += 1;
            digits_after += 1;
        }
    }

    if digits_before == 0 && digits_after == 0 {
        return None;
    }

    let mut end = scan;

    if matches!(input.as_bytes().get(scan), Some(b'e' | b'E')) {
        let mut exp_scan = scan + 1;

        if matches!(input.as_bytes().get(exp_scan), Some(b'+' | b'-')) {
            exp_scan += 1;
        }

        let exp_start = exp_scan;
        while matches!(input.as_bytes().get(exp_scan), Some(b'0'..=b'9')) {
            exp_scan += 1;
        }

        if exp_scan > exp_start {
            end = exp_scan;
        }
    }

    Some(end)
}

